const M=require('../src/models'),GP=require('../src/modules/sales/grossProfit'),fs=require('fs'),path=require('path'),XLSX=require('xlsx');const money=x=>Math.round(Number(x)*100)/100;
(async()=>{const report=await M.sequelize.transaction({isolationLevel:'REPEATABLE READ'},async transaction=>{const orders=await M.sequelize.query("SELECT o.*,s.NAME AS store_name FROM T_ORDER o LEFT JOIN T_STORE s ON s.STORE_ID=o.STORE_ID WHERE o.IS_DELETED=0 AND o.CREATE_TIME>='2026-10-01 00:00:00' AND o.CREATE_TIME<'2026-11-01 00:00:00' ORDER BY o.CREATE_TIME,o.ORDER_NO",{type:M.sequelize.QueryTypes.SELECT,transaction});const items=await M.OrderItem.findAll({where:{order_id:orders.map(x=>x.ORDER_ID||x.order_id)},raw:true,transaction});const grouped=new Map();for(const x of items){const rows=grouped.get(x.order_id)||[];rows.push(x);grouped.set(x.order_id,rows);}const mismatches=[],lineErrors=[],details=[];for(const raw of orders){const o=Object.fromEntries(Object.entries(raw).map(([k,v])=>[k.toLowerCase(),v]));const rows=grouped.get(o.order_id)||[];const subtotal=money(rows.reduce((s,x)=>s+Number(x.subtotal||0),0)),priceSum=money(rows.reduce((s,x)=>s+money(Number(x.sale_price||0)*Number(x.quantity||0)),0)),receivable=GP.calculateOrderReceivable(o),expectedFromItems=GP.calculateOrderReceivable({...o,total_amount:subtotal});const invalid=rows.filter(x=>x.sale_price===null||x.subtotal===null||x.quantity===null||!Number.isInteger(Number(x.quantity))||Number(x.quantity)<=0||Number(x.sale_price)<0||money(Number(x.sale_price)*Number(x.quantity))!==money(x.subtotal));const row={订单号:o.order_no,门店:o.store_name,状态:o.order_status,商品行数:rows.length,单价乘数量合计:priceSum,小计合计:subtotal,订单总额:Number(o.total_amount),优惠:Number(o.discount_amount),订单应收:receivable,明细扣优惠后:expectedFromItems,小计与总额差:money(subtotal-Number(o.total_amount)),应收差:money(expectedFromItems-receivable),客户实收:Number(o.actual_payment),国补:Number(o.national_subsidy),问题:[]};if(!rows.length)row.问题.push('无商品明细');if(money(subtotal-Number(o.total_amount))!==0)row.问题.push('商品小计合计与整单总额不符');if(priceSum!==subtotal)row.问题.push('单价乘数量合计与小计合计不符');if(invalid.length)row.问题.push('行金额或数量异常');row.问题=row.问题.join('；');if(row.问题){mismatches.push(row);for(const x of rows)details.push({订单号:o.order_no,门店:o.store_name,状态:o.order_status,明细ID:x.item_id,商品:x.product_name,SN:x.sn_code,数量:x.quantity,单价:x.sale_price,小计:x.subtotal,单价乘数量:money(Number(x.sale_price)*Number(x.quantity))});}for(const x of invalid)lineErrors.push({订单号:o.order_no,明细ID:x.item_id,商品:x.product_name,单价:x.sale_price,数量:x.quantity,小计:x.subtotal});}return{generatedAt:new Date(),scope:'北京时间2026-10-01至2026-11-01，全部未删除订单；状态原样列示。应收复用后台calculateOrderReceivable，总额减优惠；国补不重复扣除。仅审计不改账。',scannedOrders:orders.length,mismatches,lineErrors,details};});const dir=path.resolve(__dirname,'../backup/order-price-audit-20261104');fs.mkdirSync(dir,{recursive:true});fs.writeFileSync(path.join(dir,'october-order-amount-audit.json'),JSON.stringify(report,null,2));const wb=XLSX.utils.book_new();for(const[name,rows]of [['订单异常',report.mismatches],['异常单商品明细',report.details],['行金额异常',report.lineErrors],['核查说明',[{范围:report.scope,订单总数:report.scannedOrders,异常订单数:report.mismatches.length,异常行数:report.lineErrors.length}]]]){const ws=XLSX.utils.json_to_sheet(rows);ws['!cols']=(Object.keys(rows[0]||{})).map(k=>({wch:k==='商品'||k==='问题'?45:22}));XLSX.utils.book_append_sheet(wb,ws,name);}XLSX.writeFile(wb,path.join(dir,'10月订单金额核查.xlsx'));console.log(JSON.stringify({scanned:report.scannedOrders,count:report.mismatches.length,lineErrors:report.lineErrors.length,orders:report.mismatches.map(x=>({no:x.订单号,status:x.状态,total:x.订单总额,sum:x.小计合计,diff:x.小计与总额差,issue:x.问题})),dir}));})().catch(e=>{console.error(e);process.exitCode=1}).finally(()=>M.sequelize.close());
